class Solution {
    int secondLargest(int[] a) {
        int first = Integer.MIN_VALUE, second = Integer.MIN_VALUE;
        for (int value : a) {
            if (value > first) { second = first; first = value; }
            else if (value > second && value != first) second = value;
        }
        return second;
    }
}

