class Solution {
    int maximumChocolates(int r, int c, int[][] grid) {
        int[][] next = new int[c][c];
        for (int j1 = 0; j1 < c; j1++) for (int j2 = 0; j2 < c; j2++)
            next[j1][j2] = grid[r - 1][j1] + (j1 == j2 ? 0 : grid[r - 1][j2]);
        for (int i = r - 2; i >= 0; i--) {
            int[][] cur = new int[c][c];
            for (int j1 = 0; j1 < c; j1++) for (int j2 = 0; j2 < c; j2++) {
                int best = Integer.MIN_VALUE / 4;
                for (int d1 = -1; d1 <= 1; d1++) for (int d2 = -1; d2 <= 1; d2++) {
                    int n1 = j1 + d1, n2 = j2 + d2;
                    if (n1 >= 0 && n1 < c && n2 >= 0 && n2 < c) best = Math.max(best, next[n1][n2]);
                }
                cur[j1][j2] = best + grid[i][j1] + (j1 == j2 ? 0 : grid[i][j2]);
            }
            next = cur;
        }
        return next[0][c - 1];
    }
}

code.csharp:
public class Solution {
    public int MaximumChocolates(int r, int c, int[][] grid) {
        var next = new int[c, c];
        for (int a = 0; a < c; a++) for (int b = 0; b < c; b++)
            next[a, b] = grid[r - 1][a] + (a == b ? 0 : grid[r - 1][b]);
        for (int i = r - 2; i >= 0; i--) {
            var cur = new int[c, c];
            for (int a = 0; a < c; a++) for (int b = 0; b < c; b++) {
                int best = int.MinValue / 4;
                for (int da = -1; da <= 1; da++) for (int db = -1; db <= 1; db++) {
                    int na = a + da, nb = b + db;
                    if (na >= 0 && na < c && nb >= 0 && nb < c) best = Math.Max(best, next[na, nb]);
                }
                cur[a, b] = best + grid[i][a] + (a == b ? 0 : grid[i][b]);
            }
            next = cur;
        }
        return next[0, c - 1];
    }
}

