        memo = new bool?[arr.Length, target + 1];
        return Can(arr, 0, target);
    }

    private bool Can(int[] arr, int i, int sum) {
        if (sum == 0) return true;
        if (i == arr.Length || sum < 0) return false;
        if (memo[i, sum] != null) return memo[i, sum].Value;
        bool take = arr[i] <= sum && Can(arr, i + 1, sum - arr[i]);
        bool res = take || Can(arr, i + 1, sum);
        memo[i, sum] = res;
        return res;
    }
}

