class Solution {
    static final int INF = 1_000_000_000;
    Integer[] memo;

    int minCoins(int[] coins, int amount) {
        memo = new Integer[amount + 1];
        int ans = solve(coins, amount);
        return ans >= INF ? -1 : ans;
    }

    int solve(int[] coins, int rem) {
        if (rem == 0) return 0;
        if (memo[rem] != null) return memo[rem];
        int best = INF;
        for (int c : coins) if (c <= rem) best = Math.min(best, 1 + solve(coins, rem - c));
        return memo[rem] = best;
    }
}

