class Solution {
    Integer[][] memo;

    int unboundedKnapsack(int[] val, int[] wt, int W) {
        memo = new Integer[val.length][W + 1];
        return solve(val, wt, 0, W);
    }

    int solve(int[] val, int[] wt, int i, int cap) {
        if (i == val.length) return 0;
        if (memo[i][cap] != null) return memo[i][cap];
        int skip = solve(val, wt, i + 1, cap);
        int take = wt[i] <= cap ? val[i] + solve(val, wt, i, cap - wt[i]) : 0;
        return memo[i][cap] = Math.max(skip, take);
    }
}

