        if (memo[i, cap] != null) return memo[i, cap].Value;
        int skip = Solve(val, wt, i + 1, cap);
        int take = wt[i] <= cap ? val[i] + Solve(val, wt, i, cap - wt[i]) : 0;
        int res = Math.Max(skip, take);
        memo[i, cap] = res;
        return res;
    }
}

