        int[] dp = new int[W + 1];
        for (int c = 0; c <= W; c++)
            for (int i = 0; i < val.length; i++)
                if (wt[i] <= c) dp[c] = Math.max(dp[c], dp[c - wt[i]] + val[i]);
        return dp[W];
    }
