class Solution {
    int lcs(String s1, String s2) {
        int m = s2.length();
        int[] prev = new int[m + 1];
        for (int i = 1; i <= s1.length(); i++) {
            int[] cur = new int[m + 1];
            for (int j = 1; j <= m; j++)
                cur[j] = s1.charAt(i - 1) == s2.charAt(j - 1) ? prev[j - 1] + 1 : Math.max(prev[j], cur[j - 1]);
            prev = cur;
