class Solution {
    Boolean[][] memo;

    boolean isMatch(String s, String p) {
        memo = new Boolean[s.length()][p.length()];
        return solve(s, p, 0, 0);
    }

    boolean solve(String s, String p, int i, int j) {
        if (i == s.length()) {
            for (int k = j; k < p.length(); k++) if (p.charAt(k) != '*') return false;
            return true;
        }
        if (j == p.length()) return false;
        if (memo[i][j] != null) return memo[i][j];
        char pc = p.charAt(j);
        boolean res;
        if (pc == '*') res = solve(s, p, i + 1, j) || solve(s, p, i, j + 1);
        else if (pc == '?' || pc == s.charAt(i)) res = solve(s, p, i + 1, j + 1);
        else res = false;
        return memo[i][j] = res;
    }
}

