public class Solution {
    private bool?[,] memo;

    public bool IsMatch(string s, string p) {
        memo = new bool?[s.Length, p.Length];
        return Solve(s, p, 0, 0);
    }

    private bool Solve(string s, string p, int i, int j) {
        if (i == s.Length) {
            for (int k = j; k < p.Length; k++) if (p[k] != '*') return false;
            return true;
        }
        if (j == p.Length) return false;
        if (memo[i, j] != null) return memo[i, j].Value;
        char pc = p[j];
        bool res = pc == '*' ? Solve(s, p, i + 1, j) || Solve(s, p, i, j + 1)
            : pc == '?' || pc == s[i] ? Solve(s, p, i + 1, j + 1) : false;
        memo[i, j] = res;
        return res;
    }
}

