class Solution {
    int[][] memo;

    int maxCoins(int[] nums) {
        int n = nums.length;
        int[] a = new int[n + 2];
        a[0] = a[n + 1] = 1;
        for (int i = 0; i < n; i++) a[i + 1] = nums[i];
        memo = new int[n + 2][n + 2];
        return solve(a, 1, n);
    }

    int solve(int[] a, int l, int r) {
        if (l > r) return 0;
        if (memo[l][r] != 0) return memo[l][r];
        int best = 0;
        for (int k = l; k <= r; k++)
            best = Math.max(best, a[l - 1] * a[k] * a[r + 1] + solve(a, l, k - 1) + solve(a, k + 1, r));
        return memo[l][r] = best;
    }
}

