class Solution {
    Long[][][] memo;

    long evaluateWays(String s) {
        int n = s.length();
        memo = new Long[n][n][2];
        return solve(s, 0, n - 1, 1);
    }

    long solve(String s, int i, int j, int want) {
        if (i == j) return s.charAt(i) - '0' == want ? 1 : 0;
        if (memo[i][j][want] != null) return memo[i][j][want];
        long ways = 0;
        for (int k = i + 1; k < j; k += 2) {
            long lt = solve(s, i, k - 1, 1), lf = solve(s, i, k - 1, 0);
            long rt = solve(s, k + 1, j, 1), rf = solve(s, k + 1, j, 0);
            char op = s.charAt(k);
            if (op == '&') ways += want == 1 ? lt * rt : lt * rf + lf * rt + lf * rf;
            else if (op == '|') ways += want == 1 ? lt * rt + lt * rf + lf * rt : lf * rf;
            else ways += want == 1 ? lt * rf + lf * rt : lt * rt + lf * rf;
        }
        return memo[i][j][want] = ways;
    }
}

