        }
        boolean[] visited = new boolean[n];
        int count = 0;
        for (int i = 0; i < n; i++) {
            if (visited[i]) continue;
            count++;
            Queue<Integer> queue = new LinkedList<>();
            queue.add(i);
            visited[i] = true;
            while (!queue.isEmpty()) {
                int node = queue.poll();
                for (int next : adj.get(node))
                    if (!visited[next]) {
                        visited[next] = true;
                        queue.add(next);
                    }
            }
        }
        return count;
    }
}

