class Solution {
    int[] topoSort(int n, int[][] edges) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) adj.get(e[0]).add(e[1]);
        boolean[] visited = new boolean[n];
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < n; i++)
            if (!visited[i]) dfs(i, adj, visited, stack);
        int[] order = new int[n];
        for (int i = 0; i < n; i++) order[i] = stack.pop();
        return order;
    }

    void dfs(int node, List<List<Integer>> adj, boolean[] visited, Deque<Integer> stack) {
        visited[node] = true;
        for (int next : adj.get(node))
            if (!visited[next]) dfs(next, adj, visited, stack);
        stack.push(node);
    }
}

