class Solution {
    int wordLadderLength(String start, String target, List<String> wordList) {
        Set<String> dict = new HashSet<>(wordList);
        if (!dict.contains(target)) return 0;
        Queue<String> queue = new LinkedList<>();
        queue.add(start);
        dict.remove(start);
        int steps = 1;
        while (!queue.isEmpty()) {
            for (int size = queue.size(); size > 0; size--) {
                String word = queue.poll();
                if (word.equals(target)) return steps;
                char[] chars = word.toCharArray();
                for (int i = 0; i < chars.length; i++) {
                    char old = chars[i];
                    for (char c = 'a'; c <= 'z'; c++) {
                        if (c == old) continue;
                        chars[i] = c;
                        String next = new String(chars);
                        if (dict.remove(next)) queue.add(next);
                    }
                    chars[i] = old;
                }
            }
            steps++;
        }
        return 0;
    }
}

