class Solution {
    int[] shortestPath(int n, int[][] edges, int src) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) adj.get(e[0]).add(new int[]{e[1], e[2]});
        boolean[] visited = new boolean[n];
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < n; i++)
            if (!visited[i]) topo(i, adj, visited, stack);
        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[src] = 0;
        while (!stack.isEmpty()) {
            int node = stack.pop();
            if (dist[node] == Integer.MAX_VALUE) continue;
            for (int[] edge : adj.get(node)) {
                int next = edge[0], w = edge[1];
                dist[next] = Math.min(dist[next], dist[node] + w);
            }
        }
        for (int i = 0; i < n; i++) if (dist[i] == Integer.MAX_VALUE) dist[i] = -1;
        return dist;
    }

    void topo(int node, List<List<int[]>> adj, boolean[] visited, Deque<Integer> stack) {
        visited[node] = true;
        for (int[] edge : adj.get(node))
            if (!visited[edge[0]]) topo(edge[0], adj, visited, stack);
        stack.push(node);
    }
}

