            if (node == -1 || dist[node] == Integer.MAX_VALUE) break;
            done[node] = true;
            for (int j = 0; j < n; j++)
                if (!done[j] && w[node][j] != -1 && dist[node] + w[node][j] < dist[j])
                    dist[j] = dist[node] + w[node][j];
        }
        return dist;
