class Solution {
    int minimumMultiplications(int[] arr, int start, int end) {
        int mod = 100000;
        if (start == end) return 0;
        int[] dist = new int[mod];
        Arrays.fill(dist, -1);
        Queue<Integer> queue = new LinkedList<>();
        queue.add(start % mod);
        dist[start % mod] = 0;
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            for (int factor : arr) {
                int next = (cur * factor) % mod;
                if (dist[next] == -1) {
                    dist[next] = dist[cur] + 1;
                    if (next == end) return dist[next];
                    queue.add(next);
                }
            }
        }
        return -1;
    }
}

