public class Solution {
    public int SwimInWater(int[][] grid) {
        int n = grid.Length;
        var best = new int[n][];
        for (int i = 0; i < n; i++) {
            best[i] = new int[n];
            Array.Fill(best[i], int.MaxValue);
        }
        best[0][0] = grid[0][0];
        var pq = new PriorityQueue<int[], int>();
        pq.Enqueue(new[] { 0, 0, grid[0][0] }, grid[0][0]);
        var dirs = new int[][] { new[] { 1, 0 }, new[] { -1, 0 }, new[] { 0, 1 }, new[] { 0, -1 } };
        while (pq.Count > 0) {
            pq.TryDequeue(out var cur, out _);
            int r = cur[0], c = cur[1], t = cur[2];
            if (r == n - 1 && c == n - 1) return t;
            if (t > best[r][c]) continue;
            foreach (var d in dirs) {
