class Solution {
    int kosaraju(int n, int[][] edges) {
        List<List<Integer>> adj = new ArrayList<>();
        List<List<Integer>> rev = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
            rev.add(new ArrayList<>());
        }
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            rev.get(e[1]).add(e[0]);
        }
        boolean[] visited = new boolean[n];
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < n; i++)
            if (!visited[i]) order(i, adj, visited, stack);
        boolean[] seen = new boolean[n];
        int count = 0;
        while (!stack.isEmpty()) {
            int node = stack.pop();
            if (!seen[node]) {
                count++;
                walk(node, rev, seen);
            }
        }
        return count;
    }

    void order(int node, List<List<Integer>> adj, boolean[] visited, Deque<Integer> stack) {
        visited[node] = true;
        for (int next : adj.get(node))
            if (!visited[next]) order(next, adj, visited, stack);
        stack.push(node);
    }

    void walk(int node, List<List<Integer>> rev, boolean[] seen) {
        seen[node] = true;
        for (int next : rev.get(node))
            if (!seen[next]) walk(next, rev, seen);
    }
}

