class Solution {
    int longestSubarray(int[] arr, int k) {
        Map<Integer, Integer> firstIndex = new HashMap<>();
        int sum = 0, best = 0;
        for (int i = 0; i < arr.length; i++) {
            sum += arr[i];
            if (sum == k) best = Math.max(best, i + 1);
            if (firstIndex.containsKey(sum - k)) best = Math.max(best, i - firstIndex.get(sum - k));
            firstIndex.putIfAbsent(sum, i);
        }
        return best;
    }
}

