public class Solution {
    public int LongestSubarray(int[] arr, int k) {
        var firstIndex = new Dictionary<int, int>();
        int sum = 0, best = 0;
        for (int i = 0; i < arr.Length; i++) {
            sum += arr[i];
            if (sum == k) best = Math.Max(best, i + 1);
            if (firstIndex.ContainsKey(sum - k)) best = Math.Max(best, i - firstIndex[sum - k]);
            if (!firstIndex.ContainsKey(sum)) firstIndex[sum] = i;
        }
        return best;
    }
}

